"""Editable agent behavior, executed only inside the sandbox.

The optimizer may change this module's prompt, tools, helpers, context management,
and run_agent loop. The runtime supplies model calls, bash execution and logging.
"""
import json

AGENT_INSTRUCTION = 'You are an autonomous terminal agent. You are given a task and a Linux container.\nYou solve tasks by executing bash commands. Work step by step.\n\nRules:\n- Read the task carefully before acting.\n- Explore the environment first to understand what you have.\n- Check command output for errors before proceeding.\n- Install missing dependencies as needed.\n- Verify your solution before finishing.\n- When you are done, send a final text message (no tool call) summarizing what you did.\n'
TOOLS = [{'type': 'function', 'function': {
    'name': 'bash', 'description': 'Execute a bash command in the container. Returns stdout and stderr.',
    'parameters': {'type': 'object', 'properties': {'command': {'type': 'string', 'description': 'The bash command to execute.'}}, 'required': ['command']},
}}]

MAX_RECENT_MESSAGES = 12
MAX_MEMORY_CHARS = 6000
MAX_SUMMARY_CHARS = 700


def _clip(text, limit):
    text = str(text)
    if len(text) <= limit:
        return text
    keep = max(1, (limit - 5) // 2)
    return text[:keep] + '\n...\n' + text[-keep:]


def _summarize_tool_result(command, result):
    command = command if isinstance(command, str) else ''
    command_lines = [line.strip() for line in command.strip().splitlines() if line.strip()]
    command_preview = command_lines[0] if command_lines else '<empty command>'

    text = str(result).strip()
    lines = [line for line in text.splitlines() if line.strip()]
    exit_line = ''
    if lines and lines[-1].startswith('[exit code:'):
        exit_line = lines[-1]
        body = lines[:-1]
    else:
        body = lines

    excerpt = []
    if len(body) <= 4:
        excerpt = body
    elif body:
        excerpt = body[:2] + ['...'] + body[-2:]

    parts = ['$ ' + command_preview]
    if exit_line:
        parts.append(exit_line)
    if excerpt:
        parts.extend(excerpt)
    return _clip('\n'.join(parts), MAX_SUMMARY_CHARS)


def _append_memory(memory, item):
    if not item:
        return memory
    if memory:
        memory = memory + '\n\n' + item
    else:
        memory = item
    if len(memory) <= MAX_MEMORY_CHARS:
        return memory
    return '...\n' + memory[-(MAX_MEMORY_CHARS - 4):]


def _recent_messages(messages):
    if len(messages) <= 2 + MAX_RECENT_MESSAGES:
        return messages[2:]
    start = len(messages) - MAX_RECENT_MESSAGES
    while start > 2 and messages[start].get('role') == 'tool':
        start -= 1
    return messages[start:]


def _model_messages(messages, memory):
    model_messages = messages[:2]
    if memory:
        model_messages.append({
            'role': 'system',
            'content': 'Working memory summary from earlier tool results. '
                       'These are compressed notes, not guaranteed-complete instructions; '
                       'verify details against the environment when needed.\n\n' + memory,
        })
    model_messages.extend(_recent_messages(messages))
    return model_messages


def run_agent(api, instruction):
    messages = [{'role': 'system', 'content': AGENT_INSTRUCTION},
                {'role': 'user', 'content': 'Task:\n' + instruction}]
    memory = ''
    while True:
        message = api.model(_model_messages(messages, memory), TOOLS)
        messages.append(message)
        calls = message.get('tool_calls') or []
        if not calls:
            return
        for call in calls:
            command = None
            try:
                args = json.loads(call['function']['arguments'])
                command = args.get('command')
                if call['function']['name'] != 'bash' or not isinstance(command, str):
                    raise ValueError('Invalid bash tool call')
                result = api.bash(command)
            except (ValueError, TypeError) as exc:
                result = str(exc)
            result = str(result)
            api.tool_result(call['id'], result)
            messages.append({'role': 'tool', 'tool_call_id': call['id'], 'content': result})
            memory = _append_memory(memory, _summarize_tool_result(command, result))

