MAX_STEPS = int(os.environ.get('AGENT_MAX_STEPS', '80'))
MAX_OUTPUT_CHARS = 8000


def truncate(text, limit=MAX_OUTPUT_CHARS):
    if len(text) <= limit:
        return text
