import json
import re

AGENT_INSTRUCTION = 'You are an autonomous terminal agent. You are given a task and a Linux container.\nYou solve tasks by executing bash commands. Work step by step.\n\nRules:\n- Read the task carefully before acting.\n- Explore the environment first to understand what you have.\n- Check command output for errors before proceeding.\n- Install missing dependencies as needed.\n- Verify your solution before finishing.\n- After making changes, run at least one separate observational verification step and use its output as evidence.\n- When you are done, send a final text message (no tool call) summarizing what you did and the evidence you observed.\n'
TOOLS = [{'type': 'function', 'function': {
    'name': 'bash', 'description': 'Execute a bash command in the container. Returns stdout and stderr.',
    'parameters': {'type': 'object', 'properties': {'command': {'type': 'string', 'description': 'The bash command to execute.'}}, 'required': ['command']},
}}]

_EFFECTFUL_PATTERNS = [
    r'(^|[^\\w])(apt|apt-get|pip|pip3|npm|pnpm|yarn|cargo|gem|brew)\\s+(install|remove|uninstall|update|upgrade)\\b',
    r'(^|[^\\w])(mkdir|rmdir|rm|mv|cp|install|touch|chmod|chown|chgrp|ln|truncate)\\b',
    r'(^|[^\\w])(git)\\s+(init|clone|add|rm|mv|commit|push|pull|checkout|switch|merge|rebase|reset|clean)\\b',
    r'(^|[^\\w])(sed|perl)\\s+-i\\b',
    r'(^|[^\\w])(patch|apply_patch)\\b',
    r'(^|[^\\w])(systemctl|service)\\s+[^\n]*(start|stop|restart|reload|enable|disable)\\b',
    r'(^|[^\\w])(update-rc\\.d|chkconfig)\\b',
    r'(^|[^\\w])(make)\\s+install\\b',
    r'(^|[^\\w])(>|>>|\\btee\\b)',
]

_META_ONLY_PREFIXES = {
    'echo', 'printf', 'pwd', 'true', 'false', 'exit', 'cd', 'export', 'alias',
    'set', 'unset', 'umask', 'trap', ':'
}

_CONTEXT_TAIL_MESSAGES = 10
_MEMORY_NOTE_LIMIT = 18
_MEMORY_CHAR_BUDGET = 5000


def _normalize_command(command):
    return ' '.join(command.strip().split())


def _looks_effectful(command):
    text = _normalize_command(command).lower()
    return any(re.search(pattern, text) for pattern in _EFFECTFUL_PATTERNS)


def _looks_observational(command):
    text = _normalize_command(command)
    if not text:
        return False
    if _looks_effectful(text):
        return False
    first = text.split(None, 1)[0].lower()
    return first not in _META_ONLY_PREFIXES


def _clip_text(text, limit):
    text = str(text).strip()
    if len(text) <= limit:
        return text
    head = max(1, limit // 2 - 8)
    tail = max(1, limit - head - 5)
    return text[:head].rstrip() + ' ... ' + text[-tail:].lstrip()


def _exit_summary(result):
    match = re.search(r'\[exit code:\s*(-?\d+);\s*timed_out:\s*(True|False)\]', str(result))
    if not match:
        return ''
    timed_out = match.group(2) == 'True'
    suffix = ', timed out' if timed_out else ''
    return f' (exit {match.group(1)}{suffix})'


def _salient_lines(result, max_lines=3, max_line_len=160):
    lines = []
    for raw_line in str(result).splitlines():
        line = raw_line.strip()
        if not line or line.startswith('[exit code:'):
            continue
        lines.append(_clip_text(line, max_line_len))
        if len(lines) >= max_lines:
            break
    return lines


