    normalized = _clip_text(_normalize_command(command), 120)
    if _looks_effectful(command):
        kind = 'change'
    elif _looks_observational(command):
        kind = 'observation'
    else:
        kind = 'shell'
    note = f'- {kind}: `{normalized}`{_exit_summary(result)}'
