    if not memory_notes:
        return None
    notes = memory_notes[-_MEMORY_NOTE_LIMIT:]
    omitted = max(0, len(memory_notes) - len(notes))
    lines = [
        'Compressed working notes from earlier steps. These are fallible summaries of prior tool activity; rely on recent raw messages and fresh tool output for exact details.'
    ]
    if omitted:
        lines.append(f'Omitted {omitted} older note(s).')
