"""Editable agent behavior, executed only inside the sandbox.

The optimizer may change this module's prompt, tools, helpers, context management,
and run_agent loop. The runtime supplies model calls, bash execution and logging.
"""
import json
import re

AGENT_INSTRUCTION = 'You are an autonomous terminal agent. You are given a task and a Linux container.\nYou solve tasks by executing bash commands. Work step by step.\n\nRules:\n- Read the task carefully before acting.\n- Explore the environment first to understand what you have.\n- Check command output for errors before proceeding.\n- Install missing dependencies as needed.\n- Verify your solution before finishing.\n- After making changes, run at least one separate observational verification step and use its output as evidence.\n- When you are done, send a final text message (no tool call) summarizing what you did and the evidence you observed.\n'
TOOLS = [{'type': 'function', 'function': {
    'name': 'bash', 'description': 'Execute a bash command in the container. Returns stdout and stderr.',
    'parameters': {'type': 'object', 'properties': {'command': {'type': 'string', 'description': 'The bash command to execute.'}}, 'required': ['command']},
}}]

_EFFECTFUL_PATTERNS = [
    r'(^|[^\\w])(apt|apt-get|pip|pip3|npm|pnpm|yarn|cargo|gem|brew)\\s+(install|remove|uninstall|update|upgrade)\\b',
    r'(^|[^\\w])(mkdir|rmdir|rm|mv|cp|install|touch|chmod|chown|chgrp|ln|truncate)\\b',
    r'(^|[^\\w])(git)\\s+(init|clone|add|rm|mv|commit|push|pull|checkout|switch|merge|rebase|reset|clean)\\b',
    r'(^|[^\\w])(sed|perl)\\s+-i\\b',
    r'(^|[^\\w])(patch|apply_patch)\\b',
    r'(^|[^\\w])(systemctl|service)\\s+[^\n]*(start|stop|restart|reload|enable|disable)\\b',
    r'(^|[^\\w])(update-rc\\.d|chkconfig)\\b',
    r'(^|[^\\w])(make)\\s+install\\b',
    r'(^|[^\\w])(>|>>|\\btee\\b)',
]

_META_ONLY_PREFIXES = {
    'echo', 'printf', 'pwd', 'true', 'false', 'exit', 'cd', 'export', 'alias',
    'set', 'unset', 'umask', 'trap', ':'
}


def _normalize_command(command):
    return ' '.join(command.strip().split())


def _looks_effectful(command):
    text = _normalize_command(command).lower()
    return any(re.search(pattern, text) for pattern in _EFFECTFUL_PATTERNS)


def _looks_observational(command):
    text = _normalize_command(command)
    if not text:
        return False
    if _looks_effectful(text):
        return False
    first = text.split(None, 1)[0].lower()
    return first not in _META_ONLY_PREFIXES


def run_agent(api, instruction):
    messages = [{'role': 'system', 'content': AGENT_INSTRUCTION},
                {'role': 'user', 'content': 'Task:\n' + instruction}]
    verification_pending = False
    completion_review_pending = False

    while True:
        message = api.model(messages, TOOLS)
        messages.append(message)
        calls = message.get('tool_calls') or []
        if not calls:
            if verification_pending:
                completion_review_pending = False
                messages.append({
                    'role': 'system',
                    'content': (
                        'Do not finish yet. You have made changes since the last separate observational check. '
                        'Run one or more verification commands that directly test the requested outcome, '
                        'inspect the actual output, and only then provide the final summary.'
                    ),
                })
                continue
            if not completion_review_pending:
                completion_review_pending = True
                messages.append({
                    'role': 'system',
                    'content': (
                        'Before finishing, audit the task against observed evidence from this run. '
                        'Check whether each requested outcome is actually satisfied and supported by specific command output. '
                        'If anything is still uncertain, missing, or only inferred, do not finish: run bash commands to inspect or correct it. '
                        'If all requirements are supported by observed evidence, send the final answer now.'
                    ),
                })
                continue
            return
        completion_review_pending = False
        for call in calls:
            try:
                args = json.loads(call['function']['arguments'])
                if call['function']['name'] != 'bash' or not isinstance(args.get('command'), str):
                    raise ValueError('Invalid bash tool call')
                command = args['command']
                result = api.bash(command)
                if _looks_effectful(command):
                    verification_pending = True
                elif verification_pending and _looks_observational(command):
                    verification_pending = False
            except (ValueError, TypeError) as exc:
                result = str(exc)
            result = str(result)
            api.tool_result(call['id'], result)
            messages.append({'role': 'tool', 'tool_call_id': call['id'], 'content': result})

