}}]

_EFFECTFUL_PATTERNS = [
    r'(^|[^\\w])(apt|apt-get|pip|pip3|npm|pnpm|yarn|cargo|gem|brew)\\s+(install|remove|uninstall|update|upgrade)\\b',
    r'(^|[^\\w])(mkdir|rmdir|rm|mv|cp|install|touch|chmod|chown|chgrp|ln|truncate)\\b',
    r'(^|[^\\w])(git)\\s+(init|clone|add|rm|mv|commit|push|pull|checkout|switch|merge|rebase|reset|clean)\\b',
    r'(^|[^\\w])(sed|perl)\\s+-i\\b',
    r'(^|[^\\w])(patch|apply_patch)\\b',
    r'(^|[^\\w])(systemctl|service)\\s+[^\n]*(start|stop|restart|reload|enable|disable)\\b',
    r'(^|[^\\w])(update-rc\\.d|chkconfig)\\b',
    r'(^|[^\\w])(make)\\s+install\\b',
    r'(^|[^\\w])(>|>>|\\btee\\b)',
]

_META_ONLY_PREFIXES = {
    'echo', 'printf', 'pwd', 'true', 'false', 'exit', 'cd', 'export', 'alias',
    'set', 'unset', 'umask', 'trap', ':'
}


def _normalize_command(command):
    return ' '.join(command.strip().split())


def _looks_effectful(command):
    text = _normalize_command(command).lower()
    return any(re.search(pattern, text) for pattern in _EFFECTFUL_PATTERNS)


def _looks_observational(command):
    text = _normalize_command(command)
    if not text:
        return False
    if _looks_effectful(text):
        return False
    first = text.split(None, 1)[0].lower()
    return first not in _META_ONLY_PREFIXES


def run_agent(api, instruction):
    messages = [{'role': 'system', 'content': AGENT_INSTRUCTION},
                {'role': 'user', 'content': 'Task:\n' + instruction}]
    verification_pending = False

    while True:
        message = api.model(messages, TOOLS)
        messages.append(message)
        calls = message.get('tool_calls') or []
        if not calls:
            if verification_pending:
                messages.append({
                    'role': 'system',
                    'content': (
                        'Do not finish yet. You have made changes since the last separate observational check. '
                        'Run one or more verification commands that directly test the requested outcome, '
                        'inspect the actual output, and only then provide the final summary.'
                    ),
                })
                continue
            return
        for call in calls:
            try:
                args = json.loads(call['function']['arguments'])
                if call['function']['name'] != 'bash' or not isinstance(args.get('command'), str):
                    raise ValueError('Invalid bash tool call')
                command = args['command']
                result = api.bash(command)
                if _looks_effectful(command):
                    verification_pending = True
                elif verification_pending and _looks_observational(command):
                    verification_pending = False
            except (ValueError, TypeError) as exc:
                result = str(exc)
            result = str(result)
            api.tool_result(call['id'], result)
            messages.append({'role': 'tool', 'tool_call_id': call['id'], 'content': result})

